metadata.er-schema:
{
  "title": "looply · 用户订阅管理 实体关系图",
  "version": "v1.0 · 2026-06-09",
  "tables": [
    {
      "name": "email_subscription",
      "comment": "邮箱订阅状态",
      "columns": [
        {
          "name": "email",
          "comment": "邮箱(主体)",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "status",
          "comment": "订阅状态 subscribed/unsubscribed",
          "constraint": ""
        },
        {
          "name": "user_id",
          "comment": "账户ID(可空,注册后回填认领)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source",
          "comment": "订阅入口 footer/popup/preference",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "最近状态变更时间",
          "constraint": ""
        }
      ],
      "note": "订阅唯一权威源 · 主体=email · user_id可空 · source仅3个订阅入口"
    },
    {
      "name": "consent_record",
      "comment": "同意凭证流水",
      "columns": [
        {
          "name": "id",
          "comment": "凭证ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "email",
          "comment": "关联邮箱",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "账户ID(可空快照)",
          "constraint": ""
        },
        {
          "name": "action",
          "comment": "动作 subscribe/unsubscribe",
          "constraint": ""
        },
        {
          "name": "from_status",
          "comment": "变更前状态",
          "constraint": ""
        },
        {
          "name": "to_status",
          "comment": "变更后状态",
          "constraint": ""
        },
        {
          "name": "source",
          "comment": "触发来源 footer/popup/preference/email_unsub(二期补bounce/complaint)",
          "constraint": ""
        },
        {
          "name": "ip",
          "comment": "操作IP(审计)",
          "constraint": ""
        },
        {
          "name": "device",
          "comment": "操作设备UA快照(审计,非推送token)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "动作时间(不可篡改)",
          "constraint": ""
        }
      ],
      "note": "合规审计 · 每次动作落一条 · 不可篡改 · source含退订触发来源"
    },
    {
      "name": "user_account",
      "comment": "账户(外部)",
      "columns": [
        {
          "name": "user_id",
          "comment": "账户ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "email",
          "comment": "注册邮箱",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "注册时间",
          "constraint": ""
        }
      ],
      "note": "归用户中心/注册模块维护 · 本模块只读 · 注册不采集订阅,仅按email关联认领"
    },
    {
      "name": "push_subscription",
      "comment": "推送订阅(二期)",
      "columns": [
        {
          "name": "user_id",
          "comment": "账户ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "device_token",
          "comment": "推送令牌(APNs/FCM)",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "status",
          "comment": "订阅状态",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "最近变更时间",
          "constraint": ""
        }
      ],
      "note": "二期 · 主体=device_token(APNs/FCM推送令牌) · 一用户多设备"
    },
    {
      "name": "sms_subscription",
      "comment": "短信订阅(二期)",
      "columns": [
        {
          "name": "phone",
          "comment": "手机号(主体)",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "账户ID(可空关联)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "status",
          "comment": "订阅状态",
          "constraint": ""
        },
        {
          "name": "consent_type",
          "comment": "同意类型 TCPA express opt-in",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "最近变更时间",
          "constraint": ""
        }
      ],
      "note": "二期 · 主体=phone · TCPA express opt-in"
    }
  ],
  "relations": [
    {
      "from": "email_subscription",
      "to": "consent_record",
      "type": "1:N",
      "label": "email关联每次动作流水",
      "color": "#1565C0",
      "penwidth": 1.6
    },
    {
      "from": "user_account",
      "to": "email_subscription",
      "type": "1:0..N",
      "label": "user_id可空·订阅可先于账户·注册后认领",
      "style": "dashed"
    },
    {
      "from": "user_account",
      "to": "push_subscription",
      "type": "1:0..N",
      "label": "二期",
      "color": "#B0A0CC",
      "style": "dashed"
    },
    {
      "from": "user_account",
      "to": "sms_subscription",
      "type": "1:0..N",
      "label": "二期",
      "color": "#B0A0CC",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "subject_email": "订阅以 email 为主体,user_id 可空。支持未注册访客订阅(CAN-SPAM 管制邮箱而非账户)",
    "flat_per_channel": "按渠道分表平铺:email主键email、push主键(user_id+device_token)、sms主键phone。各表独立主键不共用主体,靠user_id关联,扩展加表不改既有表结构",
    "register_link_only": "注册不采集营销订阅,注册模块也无订阅功能。本订阅模块监听注册事件:若该email已有订阅记录则把email_subscription.user_id从null回填(一次UPDATE)。关联认领不改变同意状态,不写consent_record,不污染同意凭证表。换邮箱注册=新账户,旧邮箱订阅保持user_id=null独立存活",
    "source_two_layers": "source两层语义:email_subscription.source=订阅入口(仅footer/popup/preference 3个);consent_record.source=每次同意变更的触发来源(订阅footer/popup/preference、退订email_unsub/preference)。两者不混用",
    "consent_pure": "consent_record只记同意的授予与撤销(subscribe/unsubscribe两类),用于合规举证。关联认领等不改变同意状态的动作不进此表",
    "source_phase2_todo": "二期待补:硬退信(bounce)/垃圾投诉(complaint)类系统自动退订,EDM检测后写unsubscribe凭证。本期source不含这两值,归EDM抑制列表能力,二期再定协作写入",
    "consent_immutable": "consent_record每次状态变更落一条,不可篡改,用于合规举证。状态表只存当前态,历史进流水",
    "device_not_token": "consent_record.device是操作设备UA审计快照(如iPhone15·iOS18·Safari),与二期push_subscription.device_token(推送令牌)是完全不同概念",
    "readonly_account": "user_account归用户中心/注册模块维护,本模块只读关联,不写"
  }
}
